{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Fisetin, the closest structural analogue (Morgan 0.42), shows poor oral bioavailability in humans, supporting low systemic F for the related benzopyranone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Chrysin, a flavonoid sharing the benzopyrone core and phenolic hydroxyl, has a measured oral bioavailability of only 0.003–0.02% in humans, indicating extensive first-pass conjugation and poor systemic exposure for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Quercetin, another polyphenolic benzopyrone, is very poorly bioavailable in humans due to rapid metabolism, consistent with low systemic F for phenolic coumarin-like compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "One fisetin study reports 44.1% oral bioavailability at high dose, which would exceed the 20% threshold, but this is an outlier and dose-dependent, and other fisetin records report poor bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is 4-methylumbelliferone, a small phenolic coumarin. Although it is smaller and less polar than the flavonoid evidence molecules, the consistent experimental finding of poor/low oral bioavailability for structurally related benzopyrone polyphenols—driven by rapid conjugation and first-pass metabolism—supports a low F (<20%). The few high values come from high-dose or non-absolute measurements and do not outweigh the low-bioavailability pattern.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for 4-methylumbelliferone is present in the provided evidence.",
    "The closest analogues are flavonoids with additional B-ring phenyl and multiple hydroxyl groups; transferability to the smaller coumarin is limited.",
    "Several records are qualitative ('poor') rather than quantitative F values, adding uncertainty to threshold classification."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

